package ru.nartov.lab6;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class StudentControllerTest{@Autowired MockMvc mvc;@Test void createAndReadStudent()throws Exception{String body="{\"name\":\"Иван\",\"surname\":\"Иванов\",\"faculty\":\"ИТ\",\"age\":20}";mvc.perform(post("/api/students").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.success").value(true)).andExpect(jsonPath("$.data.id").isNumber());mvc.perform(get("/api/students")).andExpect(status().isOk()).andExpect(jsonPath("$.data").isArray());}@Test void missingStudentReturns404()throws Exception{mvc.perform(get("/api/students/99999")).andExpect(status().isNotFound()).andExpect(jsonPath("$.success").value(false));}@Test void invalidStudentReturns400()throws Exception{mvc.perform(post("/api/students").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.success").value(false));}}
